import itertools
# regions of (cup,glass,stone,metal)
regs=[r for r in itertools.product([0,1],repeat=4)]
valid=[r for r in regs if not(r[1] and r[2]) and (not r[2] or r[3])]
import itertools as it
models=[]
for n in range(1,len(valid)+1):
    for S in it.combinations(valid,n):
        if any(r[0] and r[1] for r in S):
            models.append(S)
def c1(S): return not all(r[2] for r in S if r[0]) or not any(r[0] for r in S)
def c1(S): return any(r[0] and not r[2] for r in S)
def c2(S): return not any(r[0] and r[3] for r in S)
def c3(S): return not any(r[3] and r[1] for r in S)
